WITH t AS (INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1,'M9-TPROBE3', min(milestone_id), 9997, 'подсадка самотеста', 'S', 'not_started', 'dev', 'declared' FROM project_plan_tasks WHERE project_id=$1 RETURNING id) INSERT INTO task_requirement(project_id, task_id, requirement_id) SELECT $1, t.id, sr.requirement_id FROM t, project_screen_requirements sr WHERE sr.project_id=$1 LIMIT 1
